from protocol import HERE,ROOT,load,sha

def report():
 p=ROOT/'docs/w1-shipping-runtime-qualification.json';r=load(p)
 if not r.get('all_planned_complete'):raise ValueError('qualification is incomplete; no final report or deployment claim')
 r['quality_checks']=load(HERE/'checks.json') if (HERE/'checks.json').exists() else {}
 r['Auto_descriptive_design']={'implemented':False,'possible':bool(r['certified_profiles']),'requirements':['known effectiveCPU floor','known hard and effective memoryceilings','shipping Go1.26.6/binary/image identity and supported Linuxarm64/cgroupv2 assumptions','exact dataset ID/version/hashes/index counts and frozenW1/domain scope','worker1,queue16,global2/perclient1,20attempts/anchored60sec/ClientIP,60secdeadline,sixCells'],'unknown_never_satisfies':True,'transient_free_RAM_excluded':True,'resource_numbers_alone_certify':False}
 r['fixed_profile_direction_succeeded']=bool(r['certified_profiles'])
